// Define a type alias for the Matrix
type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract the number of rows and columns from the shape
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns
    let a_len = a.len(); // Length of the input array

    // Initialize the matrix with the appropriate dimensions
    let mut matrix: Matrix<i8> = vec![vec![0; c]; r];

    // Check if the array length matches the number of rows
    if a_len == r {
        // Treat the array as a column vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[i]; // Fill each row with the corresponding element from the array
            }
        }
    } else {
        // Otherwise, the array length must match the number of columns
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[j]; // Fill each row with the corresponding element from the array
            }
        }
    }

    matrix // Return the constructed matrix
}